using System; using System.Diagnostics; using System.IO; using System.Net.Sockets;
class MultiChatStart { static bool Running(){try{using(var c=new TcpClient("127.0.0.1",8787))return true;}catch{return false;}} static void Main(){var dir=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"app");if(!File.Exists(Path.Combine(dir,"server","app.js"))){System.Windows.Forms.MessageBox.Show("Der Ordner app fehlt.","MultiChat");return;}if(!Running()){var start=new ProcessStartInfo("node","server/app.js"){WorkingDirectory=dir,UseShellExecute=false,CreateNoWindow=true};foreach(var key in new[]{"HTTP_PROXY","HTTPS_PROXY","ALL_PROXY","http_proxy","https_proxy","all_proxy"})start.EnvironmentVariables[key]="";Process.Start(start);}} }
